/** the fields that decide two alerts are the same alert. */
const IDENTITY = ["rule", "service", "instance"] as const;

/**
 * builds the fingerprint two alerts must share to be treated as one.
 * @param alert the alert as the rule engine produced it
 * @returns a stable key, safe to compare and to log
 */
export function fingerprintOf(alert: Alert): string {
  return IDENTITY.map((field) => alert[field] ?? "").join("\u0000");
}

/**
 * reports whether an alert has escalated since it last fired.
 * @param alert the alert now
 * @param previous the same fingerprint's last firing
 * @returns true when this firing is worse than the last one
 */
export function escalated(alert: Alert, previous: Alert): boolean {
  return RANK[alert.severity] > RANK[previous.severity];
}

/** how long after a resolution a refiring is treated as a flap. */
const WINDOW_MS = 10 * 60 * 1000;

/** the last resolution of each fingerprint, oldest evicted first. */
const recent = new Map<string, Resolution>();

/**
 * decides whether this firing should page.
 * @param alert the alert now
 * @param at the moment it fired
 * @returns whether to page, and why not when it declines
 */
export function shouldPage(alert: Alert, at: number): Verdict {
  const key = fingerprintOf(alert);
  const last = recent.get(key);
  if (!last) return { page: true };
  if (at - last.at > WINDOW_MS) return { page: true };
  if (escalated(alert, last.alert)) return { page: true, because: "escalated" };

  return { page: false, because: "flap" };
}

export async function dispatch(alert: Alert, at: number): Promise<void> {
  const incident = await openIncident(alert);

  const verdict = flags.flapSuppression ? shouldPage(alert, at) : { page: true };
  incident.suppressed = !verdict.page;
  if (!verdict.page) return;

  await page(incident);
}

